const uid=()=>crypto.randomUUID(), today=()=>new Date().toLocaleDateString('en-CA'), sum=a=>a.reduce((x,y)=>x+y,0), avg=a=>a.length?sum(a)/a.length:null, fmt=(n,d=1)=>n==null?'—':Number(n).toFixed(d), signed=n=>n===0?'E':n>0?'+'+n:String(n), dateFmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});
let isDemo=localStorage.getItem('hackstat.mode')!=='personal', db, view='dashboard', courseFilter='', rangeFilter='all', sortKey='date', sortDir=-1, selectedRound='', holeIndex=0, toastTimer;
function sample(){const pars=[4,4,3,5,4,3,4,5,4,4,3,5,4,4,3,4,5,4];const c={id:'demo-coastal',name:'Coastal Links',tee:'White',location:'Sample course · Sunshine Coast',rating:71.8,slope:125,holes:pars.map((p,i)=>({par:p,distance:[345,372,155,485,360,168,385,510,330,370,145,490,355,390,170,340,500,365][i],si:[7,3,15,9,5,17,1,11,13,6,18,10,4,2,16,12,8,14][i]}))};const c2={...JSON.parse(JSON.stringify(c)),id:'demo-valley',name:'Valley Greens',tee:'Blue',location:'Sample course · Hinterland',rating:72.4,slope:130};let rounds=[];for(let k=0;k<10;k++){let course=k%3===0?c2:c;let dt=new Date();dt.setDate(dt.getDate()-(9-k)*7-2);let holes=course.holes.map((h,i)=>{let diff=((i*7+k*3)%11)<2?-1:((i*3+k)%7)<3?1:((i+k)%9===0?2:0);if(k===7&&i===3)diff=-2;let score=h.par+diff,putts=diff===-2?1:((i+k)%8===0?3:((i+k)%4===0?1:2)),green=Math.max(1,score-(putts=Math.min(putts,score-1))),miss=green>h.par-2;return{score,putts,green,fairway:h.par===3?'na':['hit','hit','left','hit','right'][(i+k)%5],penalties:(i+k)%15===0&&score-putts>1?1:0,up:miss?((i+k)%3===0?'made':'miss'):'na',sand:miss&&(i+k)%5===0?(diff===0?'made':'miss'):'na',teeClub:'Driver',approach:'',firstPutt:''}});rounds.push({id:'demo-r'+k,courseId:course.id,course:JSON.parse(JSON.stringify(course)),date:dt.toLocaleDateString('en-CA'),handicapIndex:18.2,courseHandicap:20,playingHandicap:20,kind:k%3?'Social':'Competition',weather:'Fine',notes:'Illustrative sample round.',holes,completed:true});}return{version:1,courses:[c,c2],rounds,draft:null}}
function load(){try{db=JSON.parse(localStorage.getItem(isDemo?'hackstat.demo.v1':'hackstat.personal.v1'))}catch{}if(!db)db=isDemo?sample():{version:1,courses:[],rounds:[],draft:null}}
function save(){try{localStorage.setItem(isDemo?'hackstat.demo.v1':'hackstat.personal.v1',JSON.stringify(db))}catch{toast('Storage is full or unavailable. Export a backup now.')}}
function toggleDemo(){isDemo=!isDemo;localStorage.setItem('hackstat.mode',isDemo?'demo':'personal');db=null;load();courseFilter='';selectedRound='';location.hash='dashboard';render();toast(isDemo?'Viewing sample data':'Your personal scorebook — ready for your first round')}
const navItems=[['dashboard','◫','Overview'],['rounds','▤','Rounds'],['insights','↗','Insights'],['eclectic','⚑','Eclectic'],['courses','▦','Courses']];
function route(){let hash=location.hash.slice(1)||'dashboard';if(hash.startsWith('round/')){selectedRound=hash.split('/')[1];view='detail'}else view=navItems.some(x=>x[0]===hash)||hash==='play'?hash:'dashboard';render()}
function navigate(v){if(location.hash==='#'+v){view=v;render()}else location.hash=v}
function rows(){let cutoff=rangeFilter==='year'?new Date(new Date().getFullYear(),0,1):rangeFilter==='90'?new Date(Date.now()-90*864e5):null;let rr=db.rounds.filter(r=>r.completed&&(!courseFilter||r.courseId===courseFilter)&&(!cutoff||new Date(r.date+'T12:00:00')>=cutoff)).sort((a,b)=>b.date.localeCompare(a.date));return rangeFilter==='5'?rr.slice(0,5):rangeFilter==='10'?rr.slice(0,10):rr}
function stats(rr){let hh=rr.flatMap(r=>r.holes.map((h,i)=>({...h,par:r.course.holes[i].par}))).filter(h=>h.score!=null), fair=hh.filter(h=>['hit','left','right','other'].includes(h.fairway)), gir=hh.filter(h=>h.green!=null), up=hh.filter(h=>h.up&&h.up!=='na'),sand=hh.filter(h=>h.sand&&h.sand!=='na'),eagle=hh.filter(h=>(h.par===4&&h.green===1)||(h.par===5&&h.green===2));return{rounds:rr.length,holes:hh.length,scoring:avg(rr.map(r=>sum(r.holes.map(h=>h.score)))),nett:avg(rr.map(r=>sum(r.holes.map(h=>h.score))-r.playingHandicap)),fair:fair.length?100*fair.filter(h=>h.fairway==='hit').length/fair.length:null,fairN:fair.length,fairHit:fair.filter(h=>h.fairway==='hit').length,gir:gir.length?100*gir.filter(h=>h.green<=h.par-2).length/gir.length:null,girN:gir.length,girHit:gir.filter(h=>h.green<=h.par-2).length,putts:avg(rr.map(r=>sum(r.holes.map(h=>h.putts)))),puttHole:avg(hh.map(h=>h.putts)),up:up.length?100*up.filter(h=>h.up==='made').length/up.length:null,upN:up.length,upHit:up.filter(h=>h.up==='made').length,sand:sand.length?100*sand.filter(h=>h.sand==='made').length/sand.length:null,sandN:sand.length,sandHit:sand.filter(h=>h.sand==='made').length,eagle:eagle.length,eagleMade:eagle.filter(h=>h.score<=h.par-2).length,penalties:sum(hh.map(h=>h.penalties||0)),hh}}
function roundStats(r){let s=stats([r]);return{...s,gross:sum(r.holes.map(h=>h.score||0)),net:sum(r.holes.map(h=>h.score||0))-r.playingHandicap,par:sum(r.course.holes.map(h=>h.par))}}
function clubKey(c){const clean=v=>String(v||'').trim().toLocaleLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');return c.clubKey||'club:'+clean(c.name)+'|'+clean(c.location)}
function savedClubKey(id,name,location){const existing=db.courses.find(c=>c.id===id);if(existing)return clubKey(existing);const candidate={name,location},matching=db.courses.find(c=>clubKey({...c,clubKey:null})===clubKey(candidate));return matching?clubKey(matching):clubKey(candidate)}
function isHomeClub(c){return db.homeClubKey===clubKey(c)}
function isStarredClub(c){return Array.isArray(db.starredClubKeys)&&db.starredClubKeys.includes(clubKey(c))}
function orderedCourses(){const priority=c=>isHomeClub(c)?2:isStarredClub(c)?1:0;return db.courses.slice().sort((a,b)=>priority(b)-priority(a)||a.name.localeCompare(b.name,undefined,{sensitivity:'base'})||String(a.location||'').localeCompare(String(b.location||''))||a.tee.localeCompare(b.tee,undefined,{sensitivity:'base'}))}
function toggleHomeClub(id){const c=db.courses.find(c=>c.id===id);if(!c)return;const unset=isHomeClub(c);db.homeClubKey=unset?null:clubKey(c);save();render();toast(unset?'Home club cleared':c.name+' is your home club')}
function toggleStarredClub(id){const c=db.courses.find(c=>c.id===id);if(!c)return;const key=clubKey(c),wasStarred=isStarredClub(c),keys=Array.isArray(db.starredClubKeys)?db.starredClubKeys:[];db.starredClubKeys=wasStarred?keys.filter(k=>k!==key):[...keys,key];save();render();toast(wasStarred?'Club removed from starred':'Club starred')}
function filterUI(){return `<div class="filters"><label class="sr-only" for="courseFilter">Course and tees</label><select id="courseFilter" onchange="courseFilter=this.value;render()"><option value="">All courses & tees</option>${orderedCourses().map(c=>`<option value="${c.id}" ${c.id===courseFilter?'selected':''}>${isHomeClub(c)?'⌂ ':isStarredClub(c)?'★ ':''}${esc(c.name)} · ${esc(c.tee)}</option>`).join('')}</select><label class="sr-only" for="rangeFilter">Date range</label><select id="rangeFilter" onchange="rangeFilter=this.value;render()">${[['all','All time'],['year','This year'],['90','Last 90 days'],['5','Last 5 rounds'],['10','Last 10 rounds']].map(([v,l])=>`<option value="${v}" ${v===rangeFilter?'selected':''}>${l}</option>`).join('')}</select></div>`}
function heading(title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow muted">MAKE EVERY ROUND COUNT</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function metric(label,value,unit,foot,symbol='↗'){return `<div class="card metric"><div class="metric-top">${label}<span class="metric-symbol">${symbol}</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`}
function pct(v){return v==null?'—':fmt(v,0)+'%'}
function skill(label,val,foot){return `<div class="skill-row"><div class="skill-label"><span>${label} <span class="sub">${foot}</span></span><b>${pct(val)}</b></div><div class="bar"><span style="width:${val||0}%"></span></div></div>`}
function art(){return `<svg class="hero-art" viewBox="0 0 310 240" fill="none"><path d="M370 15C220-70 150 110 190 170s180 110 180 10" stroke="#335b3c" stroke-width="42"/><path d="M320 15C190-30 125 110 168 165s126 75 155 54" stroke="#668456" opacity=".28"/><ellipse cx="240" cy="188" rx="100" ry="40" fill="#446e43"/><ellipse cx="238" cy="181" rx="70" ry="29" fill="#7e9e58"/><ellipse cx="237" cy="182" rx="12" ry="4" fill="#153f2d"/><path d="M237 182V59" stroke="#dcebbd" stroke-width="3"/><path d="M239 58l49 17-49 21" fill="#c9e58b"/><circle cx="191" cy="188" r="5" fill="#e8efce"/></svg>`}
function chart(rr){if(!rr.length)return `<div class="empty"><p>Your scoring trend appears after your first round.</p></div>`;let data=[...rr].sort((a,b)=>a.date.localeCompare(b.date)).slice(-10), vals=data.map(r=>roundStats(r).gross),lo=Math.min(...vals)-3,hi=Math.max(...vals)+3,xx=i=>data.length===1?280:48+i*480/(data.length-1),yy=v=>155-(v-lo)/(hi-lo)*115;let path=vals.map((v,i)=>`${i?'L':'M'}${xx(i)},${yy(v)}`).join(' ');return `<div class="chart"><svg viewBox="0 0 570 200" role="img" aria-label="Gross score trend across ${data.length} rounds"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8bb568" stop-opacity=".25"/><stop offset="1" stop-color="#8bb568" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let y=40+i*38;return `<line x1="42" x2="542" y1="${y}" y2="${y}" stroke="#e8eee2" stroke-dasharray="3 5"/><text x="9" y="${y+4}" fill="#8c9885" font-size="10">${Math.round(hi-i*(hi-lo)/3)}</text>`}).join('')}<path d="${path} L${xx(vals.length-1)},160 L${xx(0)},160Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#36744a" stroke-width="2.5"/>${vals.map((v,i)=>`<circle cx="${xx(i)}" cy="${yy(v)}" r="4" fill="#fff" stroke="#36744a" stroke-width="2"><title>${dateFmt(data[i].date)}: ${v}</title></circle>${i%Math.ceil(data.length/5)===0?`<text x="${xx(i)}" y="188" text-anchor="middle" fill="#8c9885" font-size="9">${new Date(data[i].date+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'short'})}</text>`:''}`).join('')}</svg></div>`}
function dashboard(){let rr=rows(),s=stats(rr),nine=rr.some(r=>r.holes.length===9),eighteen=rr.some(r=>r.holes.length===18);return heading('Your game, at a glance.','A little less hack. A little more consistency.')+`<section class="hero"><div class="hero-content"><div class="eyebrow">THE NEXT ROUND STARTS HERE</div><h2>Know your game.<br>Find your next gear.</h2><p>Every fairway, every three-putt, every small win.</p><button class="button light" onclick="startRound()">${db.draft?'Resume your round':'Let’s play a round'} <span>↗</span></button></div>${art()}</section><div class="page-heading" style="margin-bottom:16px"><h2>Your scorebook</h2>${filterUI()}</div>${nine&&eighteen?'<p class="note">This selection includes 9- and 18-hole rounds. Round-score and putt totals are raw averages; use per-hole figures for comparison.</p>':''}<div class="metrics">${metric('Average gross',fmt(s.scoring),'strokes',s.rounds+' completed rounds','↗')}${metric('Fairways hit',pct(s.fair),'',s.fairHit+' / '+s.fairN+' recorded opportunities','⚑')}${metric('Greens in regulation',pct(s.gir),'',s.girHit+' / '+s.girN+' recorded holes','◎')}${metric('Average putts',fmt(s.putts),'per round',fmt(s.puttHole,2)+' putts per hole','⌁')}</div><div class="two-col"><section class="card"><div class="card-head"><div><h2>The bigger picture</h2><p>Gross score · your latest 10 selected rounds</p></div><div class="legend"><span><i></i>Gross</span></div></div>${chart(rr)}</section><section class="card"><div class="card-head"><div><h2>Around the green</h2><p>Small shots. Big difference.</p></div><span class="metric-symbol">⚑</span></div><div class="skill-list">${skill('Up & downs',s.up,`· ${s.upHit}/${s.upN}`)}${skill('Sand saves',s.sand,`· ${s.sandHit}/${s.sandN}`)}${skill('Eagle-putt conversion',s.eagle?100*s.eagleMade/s.eagle:null,`· ${s.eagleMade}/${s.eagle}`)}</div></section></div><section class="card"><div class="card-head"><div><h2>Recent rounds</h2><p>Your latest chapters on the course</p></div><button class="text-button" onclick="navigate('rounds')">All rounds ↗</button></div>${roundTable(rr.slice(0,4))}</section>`}
function roundTable(rr,sortable=false){if(!rr.length)return `<div class="empty"><h2>Your scorebook starts here.</h2><p>Add a course and record your first round. Every stat on this page will come from your golf.</p><button class="button primary" onclick="startRound()">＋ Record a round</button></div>`;let cols=[['date','DATE'],['course','COURSE / TEES'],['gross','GROSS'],['net','NETT'],['playingHandicap','HCP'],['fair','FIR'],['gir','GIR'],['putts','PUTTS'],['up','UP & DOWN'],['sand','SAND'],['eagle','EAGLE OPPS'],['penalties','PENALTIES']];return `<div class="table-wrap"><table><thead><tr>${cols.map(([k,l])=>`<th>${sortable?`<button class="table-sort" onclick="setSort('${k}')">${l} ${sortKey===k?(sortDir===1?'↑':'↓'):'↕'}</button>`:l}</th>`).join('')}<th></th></tr></thead><tbody>${rr.map(r=>{let s=roundStats(r);return `<tr class="round-row" onclick="navigate('round/${r.id}')"><td>${dateFmt(r.date)}</td><td><div class="course-cell"><span class="course-icon">⚑</span><div><strong>${esc(r.course.name)}</strong><span class="sub">${esc(r.course.tee)} · ${r.holes.length} holes</span></div></div></td><td><span class="gross">${s.gross}</span> <span class="sub">${signed(s.gross-s.par)}</span></td><td><span class="pill ${s.net<=s.par?'under':'over'}">${s.net}</span></td><td>${r.playingHandicap}</td><td>${pct(s.fair)}</td><td>${pct(s.gir)}</td><td>${s.putts}</td><td>${pct(s.up)}</td><td>${pct(s.sand)}</td><td>${s.eagle}</td><td>${s.penalties}</td><td>↗</td></tr>`}).join('')}</tbody></table></div>`}
function sortValue(r,k){if(k==='date')return r.date;if(k==='course')return r.course.name;return r[k]??roundStats(r)[k]??-1}
function setSort(k){sortDir=sortKey===k?-sortDir:1;sortKey=k;render()}
function rounds(){let rr=rows().sort((a,b)=>{let aa=sortValue(a,sortKey),bb=sortValue(b,sortKey);return(typeof aa==='string'?aa.localeCompare(bb):aa-bb)*sortDir});return heading('The round archive.','Good days, tough days. All part of your game.',`<div class="actions"><button class="button outline compact" onclick="exportCSV()">↓ Export CSV</button><button class="button primary compact" onclick="startRound()">＋ New round</button></div>`)+`<div class="page-heading">${filterUI()}<span class="sub">${rr.length} rounds · tap a heading to sort</span></div>${db.draft?`<div class="sample-note"><span>⚑ You have a round in progress at ${esc(db.draft.course.name)}.</span><button class="text-button" onclick="navigate('play')">Resume →</button></div>`:''}<section class="card">${roundTable(rr,true)}</section>`}
function insights(){let rr=rows(),s=stats(rr),hh=s.hh,scoring=['Eagle or better','Birdie','Par','Bogey','Double bogey','Triple or worse'],counts=scoring.map((_,i)=>hh.filter(h=>{let d=h.score-h.par;return i===0?d<=-2:i===5?d>=3:d===i-2}).length),scr=hh.filter(h=>h.green!=null&&h.green>h.par-2),one=hh.filter(h=>h.putts===1).length,three=hh.filter(h=>h.putts>=3).length;return heading('Find your edge.','Patterns worth taking to the practice green.',filterUI())+`<div class="metrics">${metric('Average nett',fmt(s.nett),'strokes','Using each round’s playing handicap')}${metric('Eagle opportunities',s.eagle,'',s.eagleMade+' eagles converted from eagle-putt chances','⚑')}${metric('Penalty strokes',s.penalties,'total',fmt(rr.length?s.penalties/rr.length:null)+' per round','↘')}${metric('Three-putt holes',three,'',hh.length?pct(100*three/hh.length)+' of recorded holes':'No recorded holes','⌁')}</div><div class="two-col"><section class="card"><div class="card-head"><h2>Your scoring mix</h2><span class="sub">${hh.length} holes</span></div><div class="distribution">${scoring.map((label,i)=>`<div class="distribution-row"><span>${label}</span><div class="bar"><span style="width:${hh.length?counts[i]/hh.length*100:0}%;background:${['#2c6849','#6d9c4f','#b3ca8e','#b8b990','#9a9f81','#7c886e'][i]}"></span></div><b>${counts[i]}</b></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Performance by par</h2></div><div class="table-wrap"><table><thead><tr><th>HOLE TYPE</th><th>AVG SCORE</th><th>TO PAR</th><th>HOLES</th></tr></thead><tbody>${[3,4,5].map(p=>{let a=hh.filter(h=>h.par===p);return `<tr><td>Par ${p}</td><td><b>${fmt(avg(a.map(h=>h.score)),2)}</b></td><td>${a.length?signed(Number((avg(a.map(h=>h.score))-p).toFixed(2))):'—'}</td><td>${a.length}</td></tr>`}).join('')}</tbody></table></div><div class="skill-list">${skill('Scrambling',scr.length?100*scr.filter(h=>h.score<=h.par).length/scr.length:null,`· ${scr.filter(h=>h.score<=h.par).length}/${scr.length}`)}</div></section></div><div class="stat-grid">${metric('One-putt rate',pct(hh.length?100*one/hh.length:null),'',one+' one-putt holes')}${metric('Putts per GIR',fmt(avg(hh.filter(h=>h.green!=null&&h.green<=h.par-2).map(h=>h.putts)),2),'','On holes where you hit GIR')}${metric('Fairway miss: left',s.fairN?pct(100*hh.filter(h=>h.fairway==='left').length/s.fairN):'—','','Of recorded driving opportunities')}${metric('Fairway miss: right',s.fairN?pct(100*hh.filter(h=>h.fairway==='right').length/s.fairN):'—','','Of recorded driving opportunities')}${metric('Front nine',fmt(avg(rr.filter(r=>r.holes.length>=9).map(r=>sum(r.holes.slice(0,9).map(h=>h.score))))),'strokes','Raw gross average')}${metric('Back nine',fmt(avg(rr.filter(r=>r.holes.length===18).map(r=>sum(r.holes.slice(9).map(h=>h.score))))),'strokes','18-hole rounds only')}${metric('Best gross',rr.length?Math.min(...rr.map(r=>roundStats(r).gross)):'—','','Selected rounds · raw scores')}${metric('Worst gross',rr.length?Math.max(...rr.map(r=>roundStats(r).gross)):'—','','Selected rounds · raw scores')}${metric('Eagles by hole-out',hh.filter(h=>h.score-h.par<=-2&&!((h.par===4&&h.green===1)||(h.par===5&&h.green===2))).length,'','Eagle or better without a recorded eagle-putt opportunity')}</div><p class="note">Definitions: GIR means reaching the putting green in par minus two strokes or fewer, including penalties. Scrambling means par or better after missing GIR. An up-and-down means one short-game stroke followed by one putt; record attempts explicitly. A sand save means getting down in two strokes or fewer from a greenside bunker. Percentages use recorded opportunities only.</p>`}
function eclectic(){let course=db.courses.find(c=>c.id===courseFilter)||orderedCourses()[0];if(!course)return heading('Your best-ever round.','One hole at a time.')+`<section class="card empty"><h2>A dream round, built over time.</h2><p>Add a course and play a round to start your eclectic scorecard.</p><button class="button primary" onclick="courseForm()">＋ Add course</button></section>`;let rr=rows().filter(r=>r.courseId===course.id),best=course.holes.map((_,i)=>{let opts=rr.filter(r=>r.holes[i]?.score!=null&&r.course.holes[i]?.par===course.holes[i].par).sort((a,b)=>a.holes[i].score-b.holes[i].score||a.date.localeCompare(b.date));return opts.length?{score:opts[0].holes[i].score,round:opts[0]}:null}),played=best.filter(Boolean),total=sum(played.map(h=>h.score)),par=sum(course.holes.filter((_,i)=>best[i]).map(h=>h.par));return heading('Your best-ever round.','The best of your golf, brought together.',filterUI())+`<div class="eclectic-total"><div><div class="eyebrow">${esc(course.name)} · ${esc(course.tee)} TEES</div><div class="big">${played.length?total:'—'} <small style="font-size:17px;font-weight:400;letter-spacing:0;color:#c4d4b9">${played.length===course.holes.length?'eclectic total':'partial total'}</small></div><div class="sub" style="color:#b7caad">${played.length===course.holes.length?'Your ultimate scorecard':`Incomplete · ${played.length} of ${course.holes.length} holes played`}</div></div><div class="mini-stats"><div><strong>${played.length?signed(total-par):'—'}</strong>to par</div><div><strong>${rr.length}</strong>rounds used</div></div></div><section class="card"><div class="card-head"><div><h2>Every hole. Your best.</h2><p>Gross eclectic · ${rangeFilter==='all'?'all time':'selected period'} · tap a date to revisit the round</p></div></div><div class="table-wrap"><table><thead><tr><th>HOLE</th><th>PAR</th><th>BEST SCORE</th><th>TO PAR</th><th>ACHIEVED</th></tr></thead><tbody>${course.holes.map((h,i)=>`<tr><td><b>${i+1}</b></td><td>${h.par}</td><td>${best[i]?scoreDot(best[i].score,h.par):'—'}</td><td>${best[i]?signed(best[i].score-h.par):'—'}</td><td>${best[i]?`<button class="text-button" onclick="navigate('round/${best[i].round.id}')">${dateFmt(best[i].round.date)} ↗</button>`:'Not played'}</td></tr>`).join('')}</tbody></table></div></section><p class="note">Eclectics are kept separately for each course and tee set. When “All courses” is selected, this scorecard shows ${esc(course.name)} · ${esc(course.tee)}. Use the course filter to change it. Rounds with a different par on a hole are excluded from that hole’s best score.</p>`}
function courses(){return heading('Your home turf. And beyond.','Home club first. Star your favourites to keep them close.',`<button class="button primary" onclick="courseForm()">＋ Add course / tees</button>`)+(!db.courses.length?`<section class="card empty"><h2>Where are we playing?</h2><p>Build a scorecard for any course, with hole pars, distances and stroke indexes.</p><button class="button primary" onclick="courseForm()">Add your first course</button></section>`:`<div class="course-grid">${orderedCourses().map(c=>{let rr=db.rounds.filter(r=>r.courseId===c.id);return `<section class="card course-card"><div class="course-card-heading"><div><span class="eyebrow muted">${esc(c.location||'YOUR SAVED COURSE')}</span><h2>${esc(c.name)}</h2></div><button class="club-star ${isStarredClub(c)?'is-starred':''}" onclick="toggleStarredClub('${c.id}')" aria-label="${isStarredClub(c)?'Unstar':'Star'} ${esc(c.name)}" aria-pressed="${isStarredClub(c)}" title="${isStarredClub(c)?'Remove star':'Star this club'}">${isStarredClub(c)?'★':'☆'}</button></div><div class="club-preferences"><span class="pill">${esc(c.tee)} tees</span><button class="club-home ${isHomeClub(c)?'is-home':''}" onclick="toggleHomeClub('${c.id}')" aria-pressed="${isHomeClub(c)}" aria-label="${isHomeClub(c)?'Clear':'Set'} ${esc(c.name)} ${isHomeClub(c)?'as home club':'as your home club'}" title="${isHomeClub(c)?'Clear home club':'Set as home club'}">${isHomeClub(c)?'⌂ Home club ✓':'⌂ Set home'}</button></div><div class="course-meta"><span>${c.holes.length} holes · Par ${sum(c.holes.map(h=>h.par))}</span><span>${sum(c.holes.map(h=>h.distance||0))} m</span><span>${rr.length} rounds</span></div><p class="sub">Rating ${c.rating||'—'} · Slope ${c.slope||'—'}</p><div class="actions"><button class="button primary compact" onclick="newRoundForm('${c.id}')">Play here ↗</button><button class="button outline compact" onclick="courseForm('${c.id}')">Edit scorecard</button><button class="text-button" onclick="courseFilter='${c.id}';navigate('eclectic')">Eclectic</button></div></section>`}).join('')}</div>`)+`<section class="card" style="margin-top:22px;padding:22px"><h2>Your data, in your hands.</h2><p class="muted">Rounds are saved in this browser on this device. Export a backup before switching phones or clearing browser data.</p><div class="actions"><button class="button outline" onclick="exportBackup()">↓ Back up everything</button><button class="button outline" onclick="$('#importFile').click()">↑ Restore backup</button><button class="button outline" onclick="exportCSV()">Export rounds CSV</button></div><input id="importFile" type="file" accept="application/json,.json" hidden onchange="importBackup(this.files[0])"></section>`}
function scoreDot(score,par){let d=score-par;return `<span class="score-dot ${d<=-2?'eagle':d===-1?'birdie':d===1?'bogey':d>=2?'double':''}">${score}</span>`}
function scorecard(r){let blocks=r.holes.length>9?[0,9]:[0];return blocks.map(start=>{let indexes=r.holes.slice(start,start+9).map((_,i)=>start+i);return `<div class="table-wrap"><table class="score-table"><thead><tr><th>${start===0?'FRONT':'BACK'} ${indexes.length}</th>${indexes.map(i=>`<th>${i+1}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody><tr><td>Par</td>${indexes.map(i=>`<td>${r.course.holes[i].par}</td>`).join('')}<td>${sum(indexes.map(i=>r.course.holes[i].par))}</td></tr><tr><td>Score</td>${indexes.map(i=>`<td>${r.holes[i].score!=null?scoreDot(r.holes[i].score,r.course.holes[i].par):'—'}</td>`).join('')}<td><b>${sum(indexes.map(i=>r.holes[i].score||0))}</b></td></tr><tr><td>Putts</td>${indexes.map(i=>`<td>${r.holes[i].putts??'—'}</td>`).join('')}<td>${sum(indexes.map(i=>r.holes[i].putts||0))}</td></tr><tr><td>Fairway</td>${indexes.map(i=>`<td>${({hit:'✓',left:'←',right:'→',other:'×',na:'—'})[r.holes[i].fairway]||'—'}</td>`).join('')}<td></td></tr><tr><td>GIR</td>${indexes.map(i=>`<td>${r.holes[i].green==null?'—':r.holes[i].green<=r.course.holes[i].par-2?'✓':'×'}</td>`).join('')}<td></td></tr></tbody></table></div>`}).join('')}
function detail(){let r=db.rounds.find(r=>r.id===selectedRound);if(!r)return heading('Round not found.','Return to your round archive.');let s=roundStats(r);return heading(esc(r.course.name)+'.',`${dateFmt(r.date)} · ${esc(r.course.tee)} tees · ${r.holes.length} holes · ${esc(r.kind)}`,`<div class="actions"><button class="button outline compact" onclick="editRound('${r.id}')">Edit round</button><button class="button danger compact" onclick="deleteRound('${r.id}')">Delete</button></div>`)+`<div class="metrics">${metric('Gross score',s.gross,'strokes',signed(s.gross-s.par)+' to par')}${metric('Nett score',s.net,'strokes','Playing handicap: '+r.playingHandicap)}${metric('Fairways / GIR',pct(s.fair),'',pct(s.gir)+' greens in regulation')}${metric('Total putts',s.putts,'',s.eagle+' eagle-putt opportunities')}</div><section class="card"><div class="card-head"><h2>The scorecard</h2><span class="sub">Par ${s.par}</span></div>${scorecard(r)}</section><div class="two-col" style="margin-top:22px"><section class="card"><div class="card-head"><h2>The short game</h2></div><div class="skill-list">${skill('Up & downs',s.up,`· ${s.upHit}/${s.upN}`)}${skill('Sand saves',s.sand,`· ${s.sandHit}/${s.sandN}`)}${skill('Eagle-putt conversion',s.eagle?100*s.eagleMade/s.eagle:null,`· ${s.eagleMade}/${s.eagle}`)}</div></section><section class="card" style="padding:23px"><h2>Round notes</h2><p>${esc(r.notes||'No notes recorded.').replace(/\n/g,'<br>')}</p><p class="sub">${esc(r.weather||'Conditions not recorded')} · ${s.penalties} penalty strokes</p><p class="sub">Handicap Index: ${r.handicapIndex??'—'} · Course Handicap: ${r.courseHandicap??'—'} · Playing Handicap: ${r.playingHandicap}</p></section></div><button class="text-button" onclick="navigate('rounds')">← Back to rounds</button>`}
function render(){ $('#crumb').textContent=navItems.find(n=>n[0]===view)?.[2]||(view==='play'?'On the course':'Round detail');$('#demoBtn').textContent=isDemo?'Sample data · switch':'My data · switch';let nav=navItems.map(([v,i,l])=>`<a href="#${v}" class="${view===v?'active':''}"><span class="nav-icon">${i}</span>${l}</a>`).join('');$('#nav').innerHTML=nav;$('#mobileNav').innerHTML=nav;$('#app').innerHTML=(isDemo?`<div class="sample-note"><span>EXAMPLE SCOREBOOK · These are fictional rounds to explore the app.</span><button class="text-button" onclick="toggleDemo()">Use my own data →</button></div>`:'')+({dashboard,rounds,insights,eclectic,courses,detail,play}[view]||dashboard)();}
function modal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button aria-label="Close dialog" onclick="$('#modal').close()">×</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal()}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,4500)}
function showHelp(){modal('Made for the everyday golfer.',`<p><b>Hack Stat · Golf stats for hackers.</b></p><p>A scorebook, practice guide and dream-round builder in one. Your data stays in this browser; automatic cross-device sync and official handicap updates are not included in this version.</p><p>For your phone: open the app in Safari on iPhone or Chrome on Android, then use the browser’s <b>Add to Home Screen</b> option. After the first online visit, the app shell is available offline. Private-site sign-in may still need an online connection.</p><p>Enter playing handicap manually for nett scoring. Handicap Index and Course Handicap are stored for reference. Score includes penalties; putts count strokes made from the putting green.</p><p>Export a JSON backup from Courses to transfer or protect your records. CSV exports include one row per hole.</p><button class="button primary" onclick="$('#modal').close();navigate('courses')">Manage courses & data</button>`)}
let courseEditing='';
function courseForm(id=''){courseEditing=id;let c=db.courses.find(c=>c.id===id);modal(id?'Edit course scorecard':'Find your next course.',`<form id="courseForm" onsubmit="saveCourse(event)"><div class="course-search-intro"><span>⌕</span> Search online or enter a course manually</div><div class="field course-search-field"><label for="cname">Course name</label><input id="cname" required maxlength="100" value="${esc(c?.name||'')}" placeholder="Start typing, e.g. Male…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="courseSuggestions" aria-describedby="courseLookupStatus" oninput="courseLookupInput(this.value)" onkeydown="courseLookupKey(event)"><div id="courseLookupStatus" role="status">Type at least 3 letters to search online, then choose a course and tee set.</div><div id="courseSuggestions" class="course-suggestions" role="listbox" aria-label="Matching golf courses"></div></div><div id="courseImportPanel"></div><div class="form-grid"><div class="field"><label for="ctee">Tee set</label><input id="ctee" required maxlength="70" value="${esc(c?.tee||'')}" placeholder="e.g. White"></div><div class="field"><label for="clocation">Location</label><input id="clocation" maxlength="150" value="${esc(c?.location||'')}"></div><div class="field"><label for="choles">Holes</label><select id="choles" onchange="drawCourseHoles(Number(this.value))" ${id?'disabled':''}><option value="18">18 holes</option><option value="9" ${c?.holes.length===9?'selected':''}>9 holes</option></select></div><div class="field"><label for="crating">Course rating (optional)</label><input id="crating" type="number" min="20" max="90" step=".1" value="${c?.rating||''}"></div><div class="field"><label for="cslope">Slope rating (optional)</label><input id="cslope" type="number" min="55" max="155" value="${c?.slope||''}"></div></div><p class="note">Choose the exact tee set and check imported details against the current scorecard. Use a separate entry for each tee set. Distances are in metres. Past rounds retain their original scorecard.</p><div class="table-wrap" id="courseHoleFields"></div><div class="modal-actions"><button type="button" class="button outline" onclick="$('#modal').close()">Cancel</button><button class="button primary">Save course</button></div></form>`);drawCourseHoles(c?.holes.length||18,c?.holes);initialiseCourseLookup(c)}
function drawCourseHoles(n,holes){if(!holes){holes=[...document.querySelectorAll('[data-cpar]')].map((el,i)=>({par:Number(el.value),distance:Number($(`[data-cdistance="${i}"]`).value),si:Number($(`[data-csi="${i}"]`).value)}))}$('#courseHoleFields').innerHTML=`<table class="course-holes"><thead><tr><th>HOLE</th><th>PAR</th><th>DISTANCE (m)</th><th>STROKE INDEX</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>`<tr><td>${i+1}</td><td><input aria-label="Hole ${i+1} par" data-cpar="${i}" type="number" min="3" max="6" required value="${holes[i]?.par||4}"></td><td><input aria-label="Hole ${i+1} distance" data-cdistance="${i}" type="number" min="0" max="1000" required value="${holes[i]?.distance||0}"></td><td><input aria-label="Hole ${i+1} stroke index" data-csi="${i}" type="number" min="1" max="${n}" required value="${holes[i]?.si||i+1}"></td></tr>`).join('')}</tbody></table>`}
function saveCourse(e){e.preventDefault();let holes=[...document.querySelectorAll('[data-cpar]')].map((el,i)=>({par:Number(el.value),distance:Number($(`[data-cdistance="${i}"]`).value),si:Number($(`[data-csi="${i}"]`).value)}));if(new Set(holes.map(h=>h.si)).size!==holes.length){toast('Each stroke index must be unique.');return}let c={id:courseEditing||uid(),name:$('#cname').value.trim(),tee:$('#ctee').value.trim(),location:$('#clocation').value.trim(),rating:Number($('#crating').value)||null,slope:Number($('#cslope').value)||null,holes,source:courseImportSource||null,clubKey:savedClubKey(courseEditing,$('#cname').value.trim(),$('#clocation').value.trim())};if(!c.name||!c.tee)return;let idx=db.courses.findIndex(x=>x.id===c.id);if(idx>=0)db.courses[idx]=c;else db.courses.push(c);save();$('#modal').close();navigate('courses');render();toast('Course scorecard saved')}
function startRound(){if(db.draft){navigate('play');return}if(!db.courses.length){toast('Add your first course, then start a round.');courseForm();return}newRoundForm()}
function newRoundForm(cid=''){if(db.draft){toast('Finish or discard your current round first.');navigate('play');return}modal('A fresh scorecard.',`<form onsubmit="createRound(event)"><div class="field"><label for="rcourse">Course & tees</label><select id="rcourse">${orderedCourses().map(c=>`<option value="${c.id}" ${c.id===cid?'selected':''}>${isHomeClub(c)?'⌂ ':isStarredClub(c)?'★ ':''}${esc(c.name)} · ${esc(c.tee)} · ${c.holes.length} holes</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="rdate">Round date</label><input id="rdate" type="date" required value="${today()}"></div><div class="field"><label for="rkind">Round type</label><select id="rkind"><option>Social</option><option>Competition</option><option>Practice</option></select></div><div class="field"><label for="rindex">Handicap Index (optional)</label><input id="rindex" type="number" step=".1" min="-10" max="54" placeholder="e.g. 18.2"></div><div class="field"><label for="rcoursehcp">Course Handicap (optional)</label><input id="rcoursehcp" type="number" min="-10" max="80" placeholder="e.g. 20"></div><div class="field"><label for="rhcp">Playing handicap for this round</label><input id="rhcp" type="number" min="-10" max="80" required value="0"><small>Enter the strokes you receive over these holes. Use a negative value for a plus handicap.</small></div><div class="field"><label for="rweather">Conditions (optional)</label><input id="rweather" maxlength="100" placeholder="Fine, breezy…"></div></div><p class="note">Nett score = gross score − playing handicap. This version stores your handicap values; it does not calculate or update an official handicap.</p><div class="modal-actions"><button class="button primary">Start round ↗</button></div></form>`)}
function blankHole(){return{score:null,putts:null,green:null,fairway:'na',penalties:0,up:'na',sand:'na',teeClub:'',approach:'',firstPutt:''}}
function createRound(e){e.preventDefault();let c=db.courses.find(c=>c.id===$('#rcourse').value);db.draft={id:uid(),courseId:c.id,course:JSON.parse(JSON.stringify(c)),date:$('#rdate').value,handicapIndex:$('#rindex').value===''?null:Number($('#rindex').value),courseHandicap:$('#rcoursehcp').value===''?null:Number($('#rcoursehcp').value),playingHandicap:Number($('#rhcp').value),kind:$('#rkind').value,weather:$('#rweather').value,notes:'',holes:c.holes.map(blankHole),completed:false};holeIndex=0;save();$('#modal').close();navigate('play')}
function play(){let r=db.draft;if(!r)return heading('Ready when you are.','Your next round is waiting.')+`<button class="button primary" onclick="startRound()">Start round</button>`;let i=Math.min(holeIndex,r.holes.length-1),h=r.holes[i],c=r.course.holes[i],done=r.holes.filter(h=>h.score!=null).length;return heading(esc(r.course.name)+'.',`${esc(r.course.tee)} tees · ${dateFmt(r.date)} · ${done}/${r.holes.length} holes recorded`,`<button class="button outline compact" onclick="finishRound()">Finish round</button>`)+`<div class="hole-strip">${r.holes.map((h,j)=>`<button class="hole-tab ${j===i?'active':''} ${h.score!=null?'done':''}" onclick="goHole(${j})" aria-label="Hole ${j+1}">${j+1}</button>`).join('')}</div><section class="card hole-card"><div class="hole-title"><div><span class="eyebrow muted">ON THE COURSE</span><div class="hole-number">Hole ${i+1}</div></div><div style="text-align:right"><h2>Par ${c.par}</h2><p class="sub">${c.distance||'—'} m · Stroke index ${c.si}</p></div></div><form id="holeForm" onsubmit="saveHole(event)"><label for="hscore" style="text-align:center;margin-top:22px">TOTAL STROKES <span class="sub">including penalties</span></label><div class="score-stepper"><button type="button" aria-label="Decrease score" onclick="stepScore(-1)">−</button><input id="hscore" type="number" min="1" max="30" required value="${h.score??c.par}" oninput="draftField('score',this.value)"><button type="button" aria-label="Increase score" onclick="stepScore(1)">＋</button></div><div class="hole-fields"><div class="field"><label for="hputts">Putts</label><input id="hputts" type="number" min="0" max="15" required value="${h.putts??''}" placeholder="e.g. 2" oninput="draftField('putts',this.value)"></div><div class="field"><label for="hgreen">Strokes to first reach green</label><input id="hgreen" type="number" min="1" max="30" value="${h.green??''}" placeholder="Optional" oninput="draftField('green',this.value)"><small>Include penalties. Calculates GIR & eagle opportunities.</small></div><div class="field"><label for="hpenalties">Penalty strokes</label><input id="hpenalties" type="number" min="0" max="20" value="${h.penalties}" oninput="draftField('penalties',this.value)"></div><div class="field"><label for="hfairway">Driving accuracy</label><select id="hfairway" onchange="draftField('fairway',this.value)">${[['na',c.par===3?'Not applicable / not recorded':'Not recorded / no fairway'],['hit','Fairway hit'],['left','Missed left'],['right','Missed right'],['other','Missed — other']].map(([v,l])=>`<option value="${v}" ${h.fairway===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="hup">Up-and-down attempt</label><select id="hup" onchange="draftField('up',this.value)">${attemptOptions(h.up)}</select></div><div class="field"><label for="hsand">Greenside sand save</label><select id="hsand" onchange="draftField('sand',this.value)">${attemptOptions(h.sand)}</select></div></div><details><summary class="text-button">More detail · optional</summary><div class="hole-fields"><div class="field"><label for="hclub">Tee club</label><input id="hclub" value="${esc(h.teeClub)}" maxlength="30" placeholder="e.g. Driver" oninput="draftField('teeClub',this.value)"></div><div class="field"><label for="happroach">Approach distance (m)</label><input id="happroach" type="number" min="0" max="700" value="${esc(h.approach)}" oninput="draftField('approach',this.value)"></div><div class="field"><label for="hfirst">First putt distance (m)</label><input id="hfirst" type="number" min="0" max="100" step=".1" value="${esc(h.firstPutt)}" oninput="draftField('firstPutt',this.value)"></div></div></details><div class="modal-actions"><button type="button" class="button outline" onclick="goHole(${Math.max(0,i-1)})">← Previous</button><button class="button primary">${i===r.holes.length-1?'Save final hole ✓':'Save hole & next →'}</button></div></form></section><section class="card"><div class="card-head"><h2>Your round so far</h2><span class="sub">Gross ${sum(r.holes.map(h=>h.score||0))} · ${done} holes</span></div>${scorecard(r)}</section><div class="field"><label for="rnotes">Round notes</label><textarea id="rnotes" rows="3" maxlength="3000" oninput="db.draft.notes=this.value;save()" placeholder="What worked? What needs a little practice?">${esc(r.notes)}</textarea></div><div class="actions"><button class="button primary" onclick="finishRound()">Finish & save round</button><button class="text-button danger-text" onclick="discardDraft()">Discard ${r.editing?'edits':'round'}</button></div><p class="sub">Changes autosave on this device. Blank statistics stay unrecorded; they are excluded from percentages.</p>`}
function attemptOptions(v){return [['na','No opportunity / not recorded'],['made','Opportunity — successful'],['miss','Opportunity — unsuccessful']].map(([k,l])=>`<option value="${k}" ${v===k?'selected':''}>${l}</option>`).join('')}
function draftField(key,v){if(!db.draft)return;db.draft.holes[holeIndex][key]=['score','putts','green','penalties'].includes(key)?(v===''?null:Number(v)):v;save()}
function stepScore(d){let el=$('#hscore');el.value=Math.max(1,Math.min(30,Number(el.value)+d));draftField('score',el.value)}
function goHole(i){holeIndex=i;render()}
function validHole(h){if(!Number.isInteger(h.score)||h.score<1||h.score>30)return 'Enter a total score from 1 to 30.';if(!Number.isInteger(h.putts)||h.putts<0||h.putts>h.score)return 'Enter putts between zero and your total score.';if(!Number.isInteger(h.penalties)||h.penalties<0||h.penalties+h.putts>=h.score)return 'Check penalties: at least one non-putting stroke is needed.';if(h.green!=null&&(!Number.isInteger(h.green)||h.green<1||h.green+h.putts>h.score))return 'Strokes to green plus putts cannot exceed your total score.';return ''}
function saveHole(e){e.preventDefault();let h=db.draft.holes[holeIndex];h.score=Number($('#hscore').value);h.putts=Number($('#hputts').value);h.penalties=Number($('#hpenalties').value);h.green=$('#hgreen').value===''?null:Number($('#hgreen').value);let err=validHole(h);if(err){toast(err);return}save();if(holeIndex<db.draft.holes.length-1){holeIndex++;render();window.scrollTo({top:0,behavior:'smooth'})}else{render();finishRound()}}
function finishRound(){let r=db.draft;if(!r)return;let bad=r.holes.findIndex(h=>validHole(h));if(bad>=0){holeIndex=bad;render();toast(`Complete hole ${bad+1}: ${validHole(r.holes[bad])}`);return}let prev=db.rounds.filter(x=>x.id!==r.id&&x.courseId===r.courseId),improved=r.holes.filter((h,i)=>{let a=prev.filter(p=>p.course.holes[i]?.par===r.course.holes[i].par).map(p=>p.holes[i]?.score).filter(Number.isFinite);return a.length&&h.score<Math.min(...a)}).length;r.completed=true;delete r.editing;let idx=db.rounds.findIndex(x=>x.id===r.id);if(idx>=0)db.rounds[idx]=r;else db.rounds.push(r);db.draft=null;save();navigate('round/'+r.id);toast(improved?`Round saved. ${improved} eclectic improvement${improved===1?'':'s'}!`:'Round saved. Another chapter in your game.')}
function editRound(id){if(db.draft){toast('Finish or discard your current draft before editing.');return}db.draft=JSON.parse(JSON.stringify(db.rounds.find(r=>r.id===id)));db.draft.editing=true;db.draft.completed=false;holeIndex=0;save();navigate('play')}
function discardDraft(){modal('Discard this draft?',`<p>${db.draft?.editing?'Your saved round will remain. Unsaved edits will be removed.':'This in-progress round will be removed.'}</p><div class="modal-actions"><button class="button outline" onclick="$('#modal').close()">Keep playing</button><button class="button danger" onclick="db.draft=null;save();$('#modal').close();navigate('rounds')">Discard draft</button></div>`)}
function deleteRound(id){modal('Delete this round?',`<p>This removes the round and recalculates your averages and eclectic. Export a backup first if you want to keep a copy.</p><div class="modal-actions"><button class="button outline" onclick="$('#modal').close()">Keep round</button><button class="button danger" onclick="db.rounds=db.rounds.filter(r=>r.id!=='${id}');save();$('#modal').close();navigate('rounds');toast('Round deleted')">Delete round</button></div>`)}
function download(name,content,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportBackup(){download(`hack-stat-${isDemo?'sample-':''}backup-${today()}.json`,JSON.stringify(db,null,2),'application/json');toast('Backup exported')}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(){let headers=['Date','Course','Tees','Round type','Hole','Par','Stroke index','Score','Putts','Strokes to green','Fairway','Penalties','Up and down','Sand save','Tee club','Approach m','First putt m','Gross','Handicap Index','Course Handicap','Playing Handicap','Nett','Notes'],lines=[headers,...rows().flatMap(r=>r.holes.map((h,i)=>[r.date,r.course.name,r.course.tee,r.kind,i+1,r.course.holes[i].par,r.course.holes[i].si,h.score,h.putts,h.green,h.fairway,h.penalties,h.up,h.sand,h.teeClub,h.approach,h.firstPutt,roundStats(r).gross,r.handicapIndex,r.courseHandicap,r.playingHandicap,roundStats(r).net,r.notes]))];download(`hack-stat-rounds-${today()}.csv`,'\uFEFF'+lines.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Selected rounds exported')}
function validateBackup(x){if(x?.version!==1||!Array.isArray(x.courses)||!Array.isArray(x.rounds)||x.courses.length>1000||x.rounds.length>20000)throw Error('Unsupported backup');const courseOK=c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&typeof c.tee==='string'&&Array.isArray(c.holes)&&[9,18].includes(c.holes.length)&&c.holes.every(h=>Number.isInteger(h.par)&&h.par>=3&&h.par<=6&&Number.isInteger(h.si)&&h.si>=1&&h.si<=c.holes.length);if(!x.courses.every(courseOK)||new Set(x.courses.map(c=>c.id)).size!==x.courses.length)throw Error('Invalid course data');const roundOK=r=>r&&typeof r.id==='string'&&courseOK(r.course)&&typeof r.courseId==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isFinite(r.playingHandicap)&&Array.isArray(r.holes)&&r.holes.length===r.course.holes.length;if(!x.rounds.every(r=>roundOK(r)&&r.completed===true&&r.holes.every(h=>!validHole(h)))||new Set(x.rounds.map(r=>r.id)).size!==x.rounds.length||x.draft&&!roundOK(x.draft))throw Error('Invalid round data');return x}
async function importBackup(file){if(!file)return;try{if(file.size>20e6)throw Error('Backup is too large');let incoming=validateBackup(JSON.parse(await file.text()));window.pendingBackup=incoming;modal('Restore this backup?',`<p>This replaces your current ${isDemo?'sample':'personal'} scorebook with ${incoming.courses.length} courses and ${incoming.rounds.length} rounds. Export your current backup first if needed.</p><div class="modal-actions"><button class="button outline" onclick="$('#modal').close();window.pendingBackup=null">Cancel</button><button class="button primary" onclick="db=window.pendingBackup;window.pendingBackup=null;courseFilter='';save();$('#modal').close();render();toast('Backup restored')">Restore backup</button></div>`)}catch(e){toast('Could not import: '+e.message)}}
load();window.addEventListener('hashchange',route);route();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
